 const analysis=document.createElement('section');analysis.className='analysis-workspace';analysis.id='analysis-workspace';analysis.innerHTML=`<div class="section-title">ANALYSIS + REPORTS <span>ADVANCED V3 OPTIONS</span></div><div class="analysis-inputs"><label>Design workflow<select id="code-profile">${Object.entries(CODE_PROFILES).map(([k,v])=>`<option value="${k}">${esc(v.label)}</option>`).join('')}</select></label><label>Wood grade<select id="wood-grade">${Object.entries(WOOD_GRADES).map(([k,v])=>`<option value="${k}" ${k==='DFL-No2'?'selected':''}>${esc(v.label)}</option>`).join('')}</select></label><label>Revision<input id="design-revision" value="A" maxlength="8"></label><label>Material<select id="analysis-material"><option value="timber" selected>Wood / Timber 2x4–2x12</option></select></label><label>Top chord dead (psf)<input id="analysis-dead" type="number" min="0" max="500" value="10"></label><label>Roof live (psf)<input id="analysis-rooflive" type="number" min="0" max="500" value="20"></label><label>Snow (psf)<input id="analysis-snow" type="number" min="0" max="500" value="0"></label><label>Wind pressure / uplift (psf)<input id="analysis-wind" type="number" min="0" max="500" value="20"></label><label>Bottom chord live (psf)<input id="analysis-bottomlive" type="number" min="0" max="500" value="10"></label><label>Construction load (psf)<input id="analysis-construction" type="number" min="0" max="500" value="20"></label><label>Special / solar allowance (psf)<input id="analysis-special" type="number" min="-500" max="500" value="0"></label><label>Tributary width (ft)<input id="analysis-trib" type="number" min="0.1" max="20" value="2"></label><label>Allowable axial (psi)<input id="analysis-allow" type="number" min="1" max="10000" value="875"></label><input id="analysis-fy" type="hidden" value="350"><label>Deflection limit<select id="analysis-limit"><option>240</option><option>300</option><option selected>360</option><option>480</option></select></label><label>Bearing length (mm)<input id="bearing-length" type="number" value="89" min="25" max="500"></label><label>Bearing capacity @89mm (kN)<input id="bearing-capacity" type="number" value="4" min="0.1" max="100"></label><label>Hold-down capacity (kN)<input id="hold-capacity" type="number" value="0" min="0" max="100"></label><label>Generic joint/plate capacity (kN)<input id="plate-capacity" type="number" value="0" min="0" max="500"><small>0 = unverified; use validated project/manufacturer data only</small></label><label>Compression brace trigger (mm)<input id="brace-length" type="number" value="2400" min="300" max="12000"></label><label>Plate unit cost<input id="plate-cost" type="number" value="1.5" min="0"></label><label>Member labor cost<input id="labor-cost" type="number" value="0.5" min="0"></label><label>Bearing search<select id="analysis-supports"><option value="auto">Minimize: 2–4 bearings</option><option value="ends">End bearings only</option></select></label></div><div class="analysis-actions"><button id="analyze-all" class="primary">Analyze all trusses</button><button id="analyze-selected">Analyze / size selected</button><button id="pdf-report">CadTech truss design PDF</button><button id="dxf-export">Export DXF</button><button id="png-export">Export PNG</button><button id="fab-csv">Fabrication CSV</button><button id="qa-json">QA / Revision snapshot</button><button id="about">About / limits</button></div><p class="help">Advanced preliminary timber analysis: dead, roof-live, snow, wind/uplift, bottom-chord live, construction and special-load cases; axial force, reactions, deflection, buckling screening, web/size/ply/bearing optimization. Girder/jack transfer, connector plates and jurisdiction-specific certification remain engineering-review items. Timber presets: 2x4, 2x6, 2x8, 2x10, 2x12; E = 1.6 million psi. Additional bearings are unverified proposals.</p><div id="analysis-status" role="status"></div><div id="analysis-results"></div></section>`;
 document.querySelector('main').insertBefore(analysis,document.querySelector('.engineering'));
 const building=document.createElement('section');building.className='analysis-workspace';building.id='whole-building-workspace';building.innerHTML=`<div class="section-title">WHOLE-BUILDING FRAMING <span>FLOOR · EWP · WALLS · LOAD PATH</span></div><div class="analysis-actions"><label class="file-button">Import whole building<input type="file" id="wb-import" accept=".dxf,.obj,.ifc"></label><button id="wb-import-generate" class="primary">Generate from imported building</button></div><p class="help" id="wb-import-status">Import a building DXF/OBJ. DXF is layer-aware (WALL, DOOR, WINDOW, FLOOR/SLAB, STAIR/VOID, BEAM/LVL, POST/COLUMN, ROOF/TRUSS). OBJ is envelope recognition only. IFC semantic whole-building extraction is staged for a validated IFC-property pass; existing IFC roof import remains available above.</p><div class="analysis-inputs"><label>Storeys<input id="wb-levels" type="number" min="1" max="6" value="2"></label><label>Floor system<select id="wb-floor-system"><option>Floor truss</option><option>I-Joist</option><option>LVL joists</option></select></label><label>EWP / LVL section<select id="wb-ewp">${Object.keys(EWP_TYPES).map(x=>`<option>${x}</option>`).join('')}</select></label><label>Floor truss depth (in)<input id="wb-floor-depth" type="number" min="10" max="36" value="16"></label><label>Joist/truss spacing (ft)<input id="wb-spacing" type="number" min="0.5" max="4" step="0.0833" value="1.333"></label><label>Span direction<select id="wb-orientation"><option value="width">Across building width</option><option value="length">Across building length</option></select></label><label>Wall height (ft)<input id="wb-wall-height" type="number" value="8" min="6" max="20"></label><label>Stud section<select id="wb-stud"><option>2x4</option><option selected>2x6</option><option>2x8</option></select></label><label>Stud spacing (ft)<input id="wb-stud-spacing" type="number" value="1.333" min="0.5" max="4" step="0.0833"></label><label>Floor dead (psf)<input id="wb-floor-dead" type="number" value="15"></label><label>Floor live (psf)<input id="wb-floor-live" type="number" value="40"></label><label>Wall dead (psf wall area)<input id="wb-wall-dead" type="number" value="10"></label><label class="check"><input id="wb-center-beam" type="checkbox">Add center LVL beam</label><label>Center LVL<select id="wb-lvl">${Object.keys(EWP_TYPES).filter(x=>x.startsWith('LVL')).map(x=>`<option>${x}</option>`).join('')}</select></label><label>LVL plies<input id="wb-lvl-plies" type="number" min="1" max="6" value="2"></label></div><div class="analysis-actions"><button id="wb-generate" class="primary">Generate floor + wall framing</button><button id="wb-transfer">Calculate whole-building load path</button><button id="wb-takeoff">Building take-off CSV</button><button id="wb-loadpath">Load-path CSV</button><button id="wb-json">Export building model</button><button id="wb-wall-pro">Auto wall openings + panels</button><button id="wb-floor-pro">Auto floor openings + sheathing</button><button id="wb-align">Trace point loads / alignment</button><button id="wb-wall-csv">Wall panel schedule</button><button id="wb-floor-csv">Floor framing schedule</button><button id="wb-align-csv">Alignment report</button></div><div class="analysis-inputs"><label>Wall opening side<select id="wb-open-side"><option>N</option><option>S</option><option>E</option><option>W</option></select></label><label>Opening type<select id="wb-open-type"><option>Window</option><option>Door</option></select></label><label>Opening width (ft)<input id="wb-open-width" type="number" value="4"></label><label>Opening height (ft)<input id="wb-open-height" type="number" value="4"></label><label>Sill (ft)<input id="wb-open-sill" type="number" value="3"></label><label>Floor opening width (ft)<input id="wb-void-width" type="number" value="4"></label><label>Floor opening length (ft)<input id="wb-void-length" type="number" value="10"></label></div><p class="help">Creates floor-truss / I-joist / LVL framing schedules, perimeter wall-panel stud schedules and a gravity load-path ledger from roof → floors → walls → foundation. Product-specific EWP capacities and final LVL sizes require validated manufacturer data. Openings, headers, shear walls, diaphragms, lateral/wind/seismic transfer and foundation design remain DESIGN REQUIRED.</p><details open><summary>Building Intelligence / QA</summary><div class="analysis-inputs"><label>Service level<input id="bi-service-level" type="number" min="2" max="6" value="2"></label><label>Service type<select id="bi-service-type"><option>HVAC</option><option>Plumbing</option><option>Electrical</option></select></label><label>Service width (in)<input id="bi-service-w" type="number" value="14"></label><label>Service height (in)<input id="bi-service-h" type="number" value="8"></label><label>Revision / option name<input id="bi-option" value="Current"></label></div><div class="analysis-actions"><button id="bi-coordinate" class="primary">Coordinate whole building</button><button id="bi-qa">Run clash + QA</button><button id="bi-hardware">Build hardware schedule</button><button id="bi-lateral">Create lateral model</button><button id="bi-foundation">Add foundation endpoints</button><button id="bi-service">Add / check service zone</button><button id="bi-bom">Job-wide BOM</button><button id="bi-qa-csv">QA report</button><button id="bi-hw-csv">Hardware schedule</button><button id="bi-install">Installation sequence</button><button id="bi-snapshot">Revision snapshot</button></div><p class="help">Coordinate builds the dependency graph and checks roof reaction alignment against the wall/floor model. Hardware, lateral, service penetrations and foundation capacities stay DESIGN REQUIRED until validated project/manufacturer/code data is supplied.</p><div id="bi-results"></div></details><details open><summary>Linked Structural Objects / Properties</summary><div class="analysis-inputs"><label>Object<select id="bo-object"></select></label><label>Section / material<input id="bo-section" placeholder="2x6 / LVL / I-Joist"></label><label>Spacing (ft)<input id="bo-spacing" type="number" step="0.0833"></label><label>Height (ft)<input id="bo-height" type="number" step="0.125"></label><label>Plies<input id="bo-plies" type="number" min="1" max="8"></label><label class="check"><input id="bo-bearing" type="checkbox">Bearing object</label></div><div class="analysis-actions"><button id="bo-refresh" class="primary">Refresh objects</button><button id="bo-apply">Apply properties + impact</button><button id="bo-similar">Select similar</button><button id="bo-failing">Select failing</button><button id="bo-supports">Build exact support nodes</button><button id="bo-impact-csv">Change-impact report</button><button id="bo-support-csv">Support-node report</button><button id="bo-auto-regen">Auto regenerate affected</button><button id="bo-regen-csv">Regeneration history</button></div><p class="help">Linked objects keep wall, floor, beam/post and roof-truss properties in one index. Property edits record dependency impact. Auto regeneration rebuilds affected wall/floor detailing, then refreshes roof support paths, QA, hardware and coordination without resetting unchanged project objects.</p><div id="bo-results"></div></details><details open><summary>Graphical Structural Editor</summary><div class="analysis-inputs"><label>Level<input id="ge-level" type="number" min="1" max="6" value="1"></label><label>Selected object<select id="ge-object"></select></label><label>Move X (ft)<input id="ge-dx" type="number" step="0.125" value="0"></label><label>Move Y (ft)<input id="ge-dy" type="number" step="0.125" value="0"></label><label>Width / length (ft)<input id="ge-size" type="number" step="0.125"></label><label>Height (ft)<input id="ge-height" type="number" step="0.125"></label><label>Sill (ft)<input id="ge-sill" type="number" step="0.125"></label></div><div class="analysis-inputs"><label>Snap grid (ft)<input id="ge-grid" type="number" min="0.03125" step="0.03125" value="0.25"></label><label class="check"><input id="ge-snap" type="checkbox" checked>Grid snap</label><label class="check"><input id="ge-ortho" type="checkbox">Ortho</label><label>Rotate (deg)<input id="ge-angle" type="number" value="90" step="15"></label><label>Offset (ft)<input id="ge-offset" type="number" value="1" step="0.125"></label><label>Stretch end<select id="ge-stretch-end"><option value="B">End B</option><option value="A">End A</option></select></label><label>Target object<select id="ge-target"></select></label><label>Array count<input id="ge-array-count" type="number" min="2" max="100" value="3"></label><label>Break ratio<input id="ge-break-ratio" type="number" min="0.05" max="0.95" step="0.05" value="0.5"></label><label>Selection filter<select id="ge-filter"><option value="ALL">All</option><option value="wall">Walls</option><option value="opening">Openings</option><option value="beam">Beams</option><option value="post">Posts</option><option value="floor-opening">Floor openings</option></select></label><label>Layer<select id="ge-layer"><option>ALL</option><option>WALL</option><option>OPENING</option><option>BEAM</option><option>POST</option><option>FLOOR-OPENING</option></select></label></div><div class="analysis-actions"><button id="ge-refresh" class="primary">Refresh plan</button><button id="ge-move">Move</button><button id="ge-copy">Copy</button><button id="ge-rotate">Rotate</button><button id="ge-mirror-x">Mirror X</button><button id="ge-mirror-y">Mirror Y</button><button id="ge-offset-wall">Offset wall</button><button id="ge-stretch">Stretch</button><button id="ge-join">Join wall ends</button><button id="ge-resize">Resize</button><button id="ge-add-wall">Add wall</button><button id="ge-add-beam">Add beam</button><button id="ge-add-post">Add post</button><button id="ge-undo">Undo</button><button id="ge-redo">Redo</button><button id="ge-regen">Regenerate affected</button><button id="ge-trim">Trim/Extend to target</button><button id="ge-array">Array</button><button id="ge-break">Break wall</button><button id="ge-join-collinear">Join collinear</button><button id="ge-add-window">Add window</button><button id="ge-add-door">Add door</button><button id="ge-delete">Delete</button></div><div style="overflow:auto;border:1px solid #d6e0e5;border-radius:8px;background:#f8fafb"><svg id="ge-plan" viewBox="0 0 820 520" style="display:block;width:100%;min-width:620px;max-height:620px;touch-action:none"></svg></div><p class="help">Select or drag walls, openings, beams, posts and floor openings in plan. Dragging keeps the same structural object ID, records the geometry change and regenerates linked wall/floor framing, roof support paths and QA. Geometry coordination does not replace engineering design checks.</p><div id="ge-status"></div><details open><summary>Precision Drafting + Documentation</summary><div class="analysis-inputs"><label>Object snap<select id="pd-osnap"><option>Endpoint + Midpoint + Intersection</option><option>Endpoint</option><option>Midpoint</option><option>Intersection</option><option>Perpendicular</option></select></label><label>Corner distance/radius (ft)<input id="pd-radius" type="number" value="0.5" step="0.125"></label><label>Annotation text<input id="pd-text" value="STRUCTURAL NOTE"></label><label>Grid axis<select id="pd-grid-axis"><option>X</option><option>Y</option></select></label><label>Grid position (ft)<input id="pd-grid-pos" type="number" value="0"></label><label>Grid/marker label<input id="pd-label" value="A"></label><label>Marker type<select id="pd-marker"><option>SECTION</option><option>ELEVATION</option></select></label></div><div class="analysis-actions"><button id="pd-grips">Show grips</button><button id="pd-fillet">Clean/Fillet corner</button><button id="pd-chamfer">Chamfer corner</button><button id="pd-dim">Add associative dimension</button><button id="pd-note">Add note</button><button id="pd-grid">Add grid</button><button id="pd-marker-add">Add section/elevation marker</button><button id="pd-doc-csv">Documentation CSV</button></div><p class="help" id="pd-status">Precision drafting objects are stored with the building model. Endpoint/midpoint/intersection snap data and visible grips are generated from structural objects; documentation remains associated with project levels.</p></details></details><div id="wb-status"></div><div id="wb-results"></div>`;
