 function templateOptions(t){const base=api.settings(),panels=Number($('panels').value),overhang=Number($('roof-overhang')?.value??600)/1000;if(!Number.isInteger(panels)||panels<2||panels>24||!Number.isFinite(overhang)||overhang<0||overhang>1.82881)throw Error('Panel target must be 2–24; roof overhang must be 0–1800 mm.');const shape=$('shape').value,style=$('web-style').value;return {panel:Math.min(base.panel,t.span/panels),shape,style:style==='Auto'?shapeWeb(shape):style,overhang};}
