 function parameters(){const grade=WOOD_GRADES[$('wood-grade').value]||WOOD_GRADES.CUSTOM;if(grade.allowPsi)$('analysis-allow').value=grade.allowPsi;return {material:'timber',codeProfile:$('code-profile').value,woodGrade:$('wood-grade').value,revision:$('design-revision').value||'A',dead:Number($('analysis-dead').value),roofLive:Number($('analysis-rooflive').value),snow:Number($('analysis-snow').value),wind:Number($('analysis-wind').value),bottomLive:Number($('analysis-bottomlive').value),construction:Number($('analysis-construction').value),special:Number($('analysis-special').value),trib:Number($('analysis-trib').value),allow:Number($('analysis-allow').value),fy:Number($('analysis-fy').value),limit:Number($('analysis-limit').value),supports:$('analysis-supports').value,bearingLength:Number($('bearing-length').value),bearingCapacity:Number($('bearing-capacity').value),holdDownCapacity:Number($('hold-capacity').value),plateCapacity:Number($('plate-capacity').value),braceLength:Number($('brace-length').value),plateUnitCost:Number($('plate-cost').value),memberLaborCost:Number($('labor-cost').value),currency:'USD'};}
 function invalidate(){const s=api.get();s.assembly?.trusses.forEach(t=>delete t.analysis);lastParameters=null;renderResults();}
 async function run(all=true){if(running)return;const s=api.get();if(!s.assembly)return;const p=parameters();running=true;const ids=all?s.assembly.trusses.map(t=>t.id):[s.selected];const controls=[...document.querySelectorAll('aside input,aside select,aside button,.analysis-inputs input,.analysis-inputs select,.analysis-actions button,.member-edit button')];controls.forEach(e=>e.disabled=true);try{for(let k=0;k<ids.length;k++){const i=s.assembly.trusses.findIndex(t=>t.id===ids[k]),t=s.assembly.trusses[i];if(!t)continue;$('analysis-status').textContent=`Analyzing ${k+1}/${ids.length} · ${t.id}`;await new Promise(r=>setTimeout(r,0));const o=templateOptions(t),styles=$('web-style').value==='Auto'?WEB_STYLES:[$('web-style').value];let r;try{r=analyzeAssemblyTruss(t,p,{...o,styles:t.edited?[t.webStyle||o.style]:styles,edited:!!t.edited});}catch(e){r={...t,analysis:{pass:false,status:'ERROR / REVIEW',error:e.message,members:[],extra:[]}};}if(r.analysis?.sections)r.members.forEach(m=>{const sec=r.analysis.sections[m.role];if(sec){m.section=[sec.b/1000,sec.d/1000];m.sectionName=sec.name;m.material='timber';m.thickness=(sec.t||1.6)/1000;}});r.shape=t.shape;r.webStyle=r.analysis.style||t.webStyle;s.assembly.trusses[i]=r;}engineeringPostProcess(s.assembly,p);lastParameters=p;api.refresh();renderResults();const done=s.assembly.trusses.filter(t=>t.analysis);$('analysis-status').textContent=`${done.length} analyzed · ${done.filter(t=>t.analysis.pass).length} pass isolated axial screening · whole-roof structural design remains unverified.`;}finally{running=false;controls.forEach(e=>e.disabled=false);updatePicked();}}
 function renderResults(){const ts=api.get().assembly?.trusses||[];const rows=ts.filter(t=>t.analysis);$('analysis-results').innerHTML=rows.length?'<table><thead><tr><th>Truss</th><th>Web</th><th>Ply</th><th>Ratio</th><th>Disp. mm</th><th>Extra bearings</th><th>Governing case</th><th>Status</th></tr></thead><tbody>'+rows.map(t=>`<tr><td>${t.id}</td><td>${esc(t.analysis.style||'—')}</td><td>${t.analysis.ply||t.ply||1}</td><td>${fmt(t.analysis.ratio)}</td><td>${fmt(t.analysis.displacement)}</td><td>${t.analysis.extra?.length||0}</td><td>${esc(t.analysis.governingCase||'—')}</td><td>${esc(t.analysis.status)}</td></tr>`).join('')+'</tbody></table>':'<p class="help">Not analyzed. Generate or edit the roof, then run the isolated-truss screening.</p>';}
 function selectionChanged(id,index){picked=Number.isInteger(index)?{id,index}:null;updatePicked();}
