 function remove(onlyOverhang=false){const s=api.get(),t=s.assembly?.trusses.find(t=>t.id===picked?.id),m=t?.members[picked?.index];if(!m||onlyOverhang&&m.role!=='overhang')return;undo.push({id:t.id,members:structuredClone(t.members),edited:t.edited});t.members.splice(picked.index,1);t.edited=true;invalidate();picked=null;api.refresh();updatePicked();api.notify('Member removed. Analysis invalidated; use Undo edit to restore.');}
