 function footprintSource(){const p={width:Number($('foot-width').value)*.3048,length:Number($('foot-length').value)*.3048,plate:Number($('plate').value)*.3048,pitch:Number($('pitch').value)/12,spacing:Number($('rafter-spacing').value)*.3048,style:$('roof-style').value};return parametricRoof(p);}
