 $('rebuild-webs').onclick=()=>{if(running)return;const a=api.get().assembly;if(a){configureAssembly(a);api.refresh();api.notify('Templates rebuilt from source profiles. Manual member edits were reset.');}};$('delete-member').onclick=()=>remove();$('delete-overhang').onclick=()=>remove(true);$('undo-edit').onclick=()=>{const old=undo.pop(),t=api.get().assembly?.trusses.find(t=>t.id===old?.id);if(t){t.members=old.members;t.edited=old.edited;invalidate();api.refresh();updatePicked();}};
 $('analyze-all').onclick=()=>run(true).catch(e=>api.notify(e.message,true));$('analyze-selected').onclick=()=>run(false).catch(e=>api.notify(e.message,true));document.querySelectorAll('.analysis-link').forEach(a=>a.onclick=e=>{e.preventDefault();analysis.scrollIntoView({behavior:'smooth',block:'start'});setTimeout(()=>run(false).catch(err=>api.notify(err.message,true)),250);});$('pdf-report').onclick=()=>{const s=api.get();if(!s.assembly)return;const imperial=confirm('CadTech Truss Analysis PDF units:\n\nOK = Feet / inches with fractions (nearest 1/16 in)\nCancel = Metric (mm / m)');const units=imperial?'imperial':'metric';download(`CadTech-Truss-Design-Report-${imperial?'Imperial':'Metric'}.pdf`,makeReport(s.name,s.assembly,lastParameters||{},units),'application/pdf');};$('fab-csv').onclick=()=>{const a=api.get().assembly;if(!a)return;const rows=fabricationSchedule(a),cols=['truss','member','role','size','ply','length_m','leftCut','rightCut'],csv=[cols.join(','),...rows.map(r=>cols.map(k=>String(r[k]).replaceAll(',', ';')).join(','))].join('\n');download('CadTech-Fabrication-Schedule.csv',csv,'text/csv');};$('qa-json').onclick=()=>{const a=api.get().assembly;if(a)download('CadTech-QA-Revision.json',JSON.stringify(revisionSnapshot(a,$('design-revision').value||'A'),null,2),'application/json');};$('dxf-export').onclick=()=>{const a=api.get().assembly;if(a)download('roof-framing.dxf',exportDXF(a),'application/dxf');};$('png-export').onclick=()=>{const url=api.png();if(url){const a=document.createElement('a');a.href=url;a.download='roof-viewport.png';a.click();}};
 $('save-project').onclick=()=>{const s=api.get();download('rafter-project.json',JSON.stringify({version:2,...s,settings:api.settings(),options:uiValues(),wallSegments},null,2),'application/json');};$('load-project').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>30*1024*1024)throw Error('Project exceeds 30 MB');const d=JSON.parse(await f.text());if(d.version!==2||!d.source||!Array.isArray(d.source.axes)||!d.assembly||!Array.isArray(d.assembly.trusses)||d.assembly.trusses.length>1500)throw Error('Choose a Rafter v2 saved project.');for(const t of d.assembly.trusses){if(typeof t.id!=='string'||!/^[-A-Za-z0-9_]{1,30}$/.test(t.id)||!['Common','Stepdown','Girder','Front jack','Side jack','Hip carrier','Mono','Unclassified'].includes(t.type)||![1,2,3,4].includes(t.ply)||!Array.isArray(t.members)||t.members.length>500||!Array.isArray(t.profile)||!Array.isArray(t.normal)||t.members.some(m=>!Array.isArray(m.a)||!Array.isArray(m.b)||[...m.a,...m.b].some(x=>!Number.isFinite(x))))throw Error('Invalid saved geometry');}applyValues(d.options);if(d.settings){$('heel').value=d.settings.heel*1000;$('panel').value=d.settings.panel*1000;$('hips').checked=!!d.settings.inferHips;}wallSegments=d.wallSegments||[];api.restore(d);lastParameters=d.assembly.trusses.some(t=>t.analysis)?parameters():null;undo=[];picked=null;updatePicked();renderResults();api.notify('Project restored, including source geometry and member edits.');}catch(e){api.notify(e.message,true);}$('load-project').value='';};
